{"ruta":"public/script.js","contenido":"// public/script.js

async function fetchTasks() {
  try {
    const res = await fetch('/api/tasks');
    const tasks = await res.json();
    renderTasks(tasks);
  } catch (e) {
    console.error('Error fetching tasks:', e);
  }
}

function renderTasks(tasks) {
  const ul = document.getElementById('tasks');
  ul.innerHTML = '';
  tasks.forEach(task => {
    const li = document.createElement('li');
    li.className = 'task';
    li.innerHTML = `
      <span${task.completed ? ' class="completed"' : ''}>${task.title}</span>
    `;
    // Button to toggle completed
    const btnToggle = document.createElement('button');
    btnToggle.textContent = task.completed ? '◉' : '✓';
    btnToggle.onclick = async () => {
      await fetch(`/api/tasks/${task.id}`, { method: 'PATCH' });
      await fetchTasks();
    };
    // Button to delete
    const btnDelete = document.createElement('button');
    btnDelete.textContent = '✕';
    btnDelete.onclick = async () => {
      await fetch(`/api/tasks/${task.id}`, { method: 'DELETE' });
      await fetchTasks();
    };
    li.appendChild(btnToggle);
    li.appendChild(btnDelete);
    ul.appendChild(li);
  });
}

document.addEventListener('DOMContentLoaded', () => {
  fetchTasks();
  const form = document.getElementById('taskForm');
  form.addEventListener('submit', async e => {
    e.preventDefault();
    const titleInput = document.getElementById('title');
    const title = titleInput.value.trim();
    if (!title) return;
    await fetch('/api/tasks', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ title })
    });
    titleInput.value = '';
    await fetchTasks();
  });
});
"}

